import { Launchpage } from "Hindi-olabsnxtg-library";
import React from "react";
import { useTranslation } from "react-i18next";
import ActStartPopupContent from "./ActStartPopupContent";

export const Ll5_launchpage = () => {
  const { t, i18n } = useTranslation();
  var arr = [t("learning_out_title1")];
  return (
    <Launchpage
      L_title="विलोम शब्द"
      L_objective={t("उद्देश्य")}
      L_act_objective={t("विलोम शब्दों को पहचानना।")}
      L_array={arr}
      L_learning_outcome={t("learning_out_title")}
      L_startbutton={t("start")}
      L_actstartPopup_content_comp={<ActStartPopupContent />}
      L_actstartPopup_content_title={t("what_we_are_going_to_learn_title")}
      L_ok="हाँ।"
      L_cancel="रद्द करें।"
    />
  );
};
