import React, { useState } from "react";
import ReactPlayer from "react-player";
import song from "../assets/Gameaudio/song.mp3";
import { VolumeOffOutlined, VolumeUpOutlined } from "@mui/icons-material";
import { Button, Tooltip } from "@mui/material";
function ReactAudioPlayer() {
  const [isMuted, setIsMuted] = useState(false);

  const toggleMute = () => {
    setIsMuted((prevIsMuted) => !prevIsMuted);
  };

  return (
    <div className="col-4 d-flex justify-content-center align-items-center">
      <ReactPlayer
        url={song}
        loop={true}
        playing={!isMuted}
        muted={false}
        width="50px"
        height="50px"
        volume="0.3"
      />

      <Tooltip title="आवाज" placement="bottom" arrow>
        <Button
          onClick={toggleMute}
          className="rounded-pill my-2 col-12"
          variant="contained"
          color="warning"
        >
          {isMuted ? <VolumeOffOutlined /> : <VolumeUpOutlined />}
        </Button>
      </Tooltip>
    </div>
  );
}

export default ReactAudioPlayer;
