import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import Button from "@mui/material/Button";
import Dialog from "@mui/material/Dialog";
import DialogActions from "@mui/material/DialogActions";
import DialogContent from "@mui/material/DialogContent";
import DialogTitle from "@mui/material/DialogTitle";
import Slide from "@mui/material/Slide";
import { Tooltip } from "@mui/material";

function CountdownTimer({
  initialSeconds,
  shuffleCards,
  seconds,
  setSeconds,
  quenum,
  setQuenum,
  setScore,
  question,
  resetGame,
  score,
  open1,
  opencongo,
  positivescore,
  negativescore,
  progress,
}) {
  var [open, setOpen] = useState(false);

  useEffect(() => {
    let interval;
    console.log("helloout: " + open1);
    if (seconds > 0) {
      console.log("helloin: " + open1);

      interval = setInterval(() => {
        setSeconds((prevSeconds) => prevSeconds - 1);
      }, 1000);
    }

    if (open1 == false && seconds == 0 && opencongo == false) {
      setOpen(true);
      console.log("helloinif: " + open1);
    }

    return () => {
      clearInterval(interval);
    };
  }, [open1, seconds]);

  //////dialog box
  const navigate = useNavigate();

  const handleClose = () => {
    setOpen(false);
    navigate("/");
  };

  const handleYes = () => {
    // Handle 'Yes' action here
    setOpen(false);
    shuffleCards();
    setSeconds(initialSeconds);
    setQuenum(0);
    setScore(0);
    console.log(initialSeconds);
    console.log(quenum);
    resetGame();
    question.map((item, index) => {
      item.vis = "visible";
      item.explod = false;
    });
  };

  return (
    <div className="col-6">
      <Tooltip title="घड़ी" placement="bottom" arrow>
        <Button
          className="rounded-pill my-2 col-12"
          variant="contained"
          color="success"
          style={{
            cursor: "none",
          }}
        >
          घड़ी: {seconds}
        </Button>
      </Tooltip>

      <Dialog
        open={open}
        TransitionComponent={Slide}
        keepMounted
        // onClose={handleClose}
        aria-labelledby="alert-dialog-slide-title"
        aria-describedby="alert-dialog-slide-description"
      >
        <DialogTitle
          className="fs-4 fst-italic fw-bolder text-center text-danger"
          id="alert-dialog-slide-title "
        >
          <h5 className="text-dark">आप इसे पुनः प्रयास कर सकते हैं। </h5>
        </DialogTitle>
        <DialogContent>
          <div className="bg-inf d-flex justify-content-center align-items-center">
            <div className="card" style={{ width: "18rem" }}>
              <div
                className="d-flex justify-content-center align-items-center"
                style={{ fontSize: "7rem" }}
              >
                😞
              </div>
              <div className="card-body ">
                <p className="card-text text-center fw-bold fs-5 text-pri">
                  <div>स्कोर : {score} 👍</div>
                  <div className="text-success">
                    सही जवाब : {positivescore} 😄
                  </div>
                  <div className="text-danger">
                    गलत जवाब : {negativescore} 🥲
                  </div>
                  <div className="text-primary">
                    कुल सवाल : {positivescore + 1} 🙂
                  </div>
                  <div className=" mt-1 bg-danger text-warning  rounded-5">
                    {progress}%
                  </div>
                </p>
              </div>
            </div>
          </div>
        </DialogContent>

        <DialogActions className="d-flex justify-content-evenly">
          <Button
            className="rounded-pill"
            variant="contained"
            color="secondary"
            onClick={handleYes}
          >
            पुनः प्रयास करें।
          </Button>
        </DialogActions>
      </Dialog>
    </div>
  );
}

export default CountdownTimer;
