import React, { useState } from "react";
import Button from "@mui/material/Button";
import Dialog from "@mui/material/Dialog";
import DialogActions from "@mui/material/DialogActions";
import DialogTitle from "@mui/material/DialogTitle";
import Slide from "@mui/material/Slide";
import { useNavigate } from "react-router-dom";
import { PowerSettingsNew } from "@mui/icons-material";
import { Tooltip } from "@mui/material";

function MyDialog() {
  const navigate = useNavigate();
  const [open, setOpen] = useState(false);

  const handleClickOpen = () => {
    setOpen(true);
  };

  const handleClose = () => {
    setOpen(false);
  };

  const handleYes = () => {
    // Handle 'Yes' action here
    setOpen(false);
    navigate("/");
  };

  return (
    <div className="col-4">
      <Tooltip title="बंद करें। " placement="bottom" arrow>
        <Button
          className="rounded-pill my-2 col-12"
          variant="contained"
          color="error"
          onClick={handleClickOpen}
        >
          <PowerSettingsNew />
        </Button>
      </Tooltip>

      <Dialog
        open={open}
        TransitionComponent={Slide}
        keepMounted
        // onClose={handleClose}
        aria-labelledby="alert-dialog-slide-title"
        aria-describedby="alert-dialog-slide-description"
      >
        <DialogTitle id="alert-dialog-slide-title">
          <div className="fs-1 text-center ">🤔</div>
          <div className="text-center fw-bolder">
          क्या सही में आपको खेल से बाहर जाना हैं ?
          </div>
        </DialogTitle>

        <DialogActions className="d-flex justify-content-evenly">
          <Button
            className="rounded-pill"
            variant="contained"
            color="secondary"
            onClick={handleYes}
          >
            हाँ।
          </Button>
          <Button
            onClick={handleClose}
            className="rounded-pill"
            variant="contained"
            color="warning"
          >
            रद्द करें।
          </Button>
        </DialogActions>
      </Dialog>
    </div>
  );
}

export default MyDialog;
